CREATE OR REPLACE FUNCTION public.create_compatibility_results(invite_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    invite_row RECORD;
    inviter_aura_id INT;
    recipient_aura_id INT;
    comp_score FLOAT;
BEGIN
    -- Fetch the invite row
    SELECT *
    INTO invite_row
    FROM invites
    WHERE id = invite_id;

    IF NOT FOUND THEN
        RAISE LOG 'No invite found with id = %', invite_id;
        RETURN;
    END IF;

    RAISE LOG 'invite_id: %', invite_id;
    RAISE LOG 'inviter_user_id: %, recipient_user_id: %', invite_row.inviter_user_id, invite_row.recipient_user_id;

    IF invite_row.inviter_user_id IS NOT NULL AND invite_row.recipient_user_id IS NOT NULL AND invite_row.relationship_type IS NOT NULL THEN

        -- Get latest aura_id for inviter
        SELECT aura_id INTO inviter_aura_id
        FROM user_quiz_results
        WHERE user_id = invite_row.inviter_user_id AND aura_id IS NOT NULL
        ORDER BY quiz_date DESC
        LIMIT 1;

        RAISE LOG 'inviter_aura_id: %', inviter_aura_id;

        -- Get latest aura_id for recipient
        SELECT aura_id INTO recipient_aura_id
        FROM user_quiz_results
        WHERE user_id = invite_row.recipient_user_id AND aura_id IS NOT NULL
        ORDER BY quiz_date DESC
        LIMIT 1;

        RAISE LOG 'recipient_aura_id: %', recipient_aura_id;

        -- Proceed only if both aura_ids are available
        IF inviter_aura_id IS NOT NULL AND recipient_aura_id IS NOT NULL THEN
            -- Calculate compatibility score
            SELECT compatibility_score INTO comp_score
            FROM animal_compatibility
            WHERE animal_a_id = inviter_aura_id AND animal_b_id = recipient_aura_id;

            RAISE LOG 'compatibility_score: %', comp_score;

            -- Insert the compatibility results
            INSERT INTO compatibility_results (
                invite_id,
                user_a_id,
                user_b_id,
                user_a_aura_id,
                user_b_aura_id,
                compatibility_score,
                relationship_type
            )
            VALUES (
                invite_row.id,
                invite_row.inviter_user_id,
                invite_row.recipient_user_id,
                inviter_aura_id,
                recipient_aura_id,
                comp_score,
                invite_row.relationship_type
            );

            RAISE LOG 'Inserted compatibility result for invite_id: %', invite_row.id;
        ELSE
            RAISE LOG 'Missing aura_id: inviter_aura_id = %, recipient_aura_id = %', inviter_aura_id, recipient_aura_id;
        END IF;
    ELSE
        RAISE LOG 'Required invite fields are missing (inviter_user_id, recipient_user_id, relationship_type)';
    END IF;
END;
$function$
